import { test } from "node:test";
import assert from "node:assert/strict";
import { squarify, rate, contrast, readableOn, TM_COLORS } from "../src/util.js";
import { translator } from "../src/i18n.js";
import { bytes, number, dateTime } from "../src/format.js";

test("squarify fills the rectangle in proportion and without overlap", () => {
  const items = [60, 25, 10, 5].map((v, i) => ({ v, i }));
  const rects = squarify(items, 0, 0, 600, 220);
  assert.equal(rects.length, 4);
  const area = (r) => r.w * r.h;
  const total = rects.reduce((a, r) => a + area(r), 0);
  assert.ok(Math.abs(total - 600 * 220) < 1e-6);
  for (const r of rects) {
    assert.ok(Math.abs(area(r) / total - r.v / 100) < 1e-9, "area follows the value");
    assert.ok(r.x >= -1e-9 && r.y >= -1e-9 && r.x + r.w <= 600 + 1e-6 && r.y + r.h <= 220 + 1e-6);
  }
  for (let a = 0; a < rects.length; a++) {
    for (let b = a + 1; b < rects.length; b++) {
      const p = rects[a];
      const q = rects[b];
      const overlap =
        Math.min(p.x + p.w, q.x + q.w) - Math.max(p.x, q.x) > 1e-6 &&
        Math.min(p.y + p.h, q.y + q.h) - Math.max(p.y, q.y) > 1e-6;
      assert.ok(!overlap, "no two areas overlap");
    }
  }
  assert.deepEqual(squarify([], 0, 0, 10, 10), []);
  assert.deepEqual(squarify([{ v: 0 }], 0, 0, 10, 10), []);
});

test("rate reads like a person would say it", () => {
  const t = translator({ language: "en" });
  assert.equal(rate(0, t, "en"), "–");
  assert.match(rate(86400 / 2, t, "en"), /2/);
  assert.match(rate(24 * 60, t, "en"), /1/);
  assert.match(rate(6, t, "en"), /6/);
});

test("translator: language, fallback, placeholders and one of something", () => {
  const de = translator({ language: "de" });
  const en = translator({ locale: { language: "en-GB" } });
  assert.equal(de("window_rows", { n: "1" }), "1 Zeile");
  assert.equal(de("window_rows", { n: "1.000" }), "1.000 Zeilen");
  assert.equal(en("window_rows", { n: 2 }), "2 rows");
  // the counted value decides, not another number in the text
  assert.match(de("stats_ret_frees", { rows: "5", n: 1, bytes: "1 KB", date: "x" }), /5 Zeilen/);
  assert.equal(translator({ language: "xx" })("window_rows", { n: 3 }), "3 rows");
  assert.equal(en("no_such_key"), "no_such_key");
});

test("formatting", () => {
  assert.equal(bytes(0, "en"), "0 B");
  assert.match(bytes(1536, "en"), /KB/);
  assert.equal(number(1234, "de"), "1.234");
  assert.match(dateTime(1795850000, "en", true), /\d{1,2}:\d{2}:\d{2}/);
  assert.equal(dateTime(null, "en"), "–");
});

test("treemap labels are readable on every area colour", () => {
  assert.ok(Math.abs(contrast("#ffffff", "#000000") - 21) < 1e-9);
  assert.equal(contrast("#777777", "#777777"), 1);
  for (const fill of TM_COLORS) {
    // large bold text (WCAG AA): 3:1 at least
    assert.ok(contrast(fill, readableOn(fill)) >= 3, `${fill} with ${readableOn(fill)}`);
  }
  assert.equal(readableOn("#1f1f1f"), "#ffffff");
  assert.equal(readableOn("#f5f5f5"), "#1f1f1f");
});
